<?php
$contentType = in_array($page, ['actualites','promotions','hebergements','activites'], true) ? $page : 'actualites';
$contentLabels = ['actualites'=>'Actualités','promotions'=>'Promotions','hebergements'=>'Hébergements','activites'=>'Activités'];
$slug = trim((string)($_GET['slug'] ?? ''));
$endpoint = 'api/contenus/' . $contentType . ($slug !== '' ? '/' . rawurlencode($slug) : '');
$payload = ClientApi::data($api->request('GET', $endpoint));
$items = $slug !== '' ? [$payload] : (is_array($payload['items'] ?? null) ? $payload['items'] : []);
?>
<section class="page-heading"><p class="eyebrow">Découvrez la Côte d’Ivoire</p><h1><?=client_h($contentLabels[$contentType])?></h1><p>Informations publiées par l’équipe Tourisme Ivoire.</p></section>
<nav class="content-tabs" aria-label="Explorer les contenus"><?php foreach($contentLabels as $key=>$label):?><a class="btn <?= $key===$contentType?'btn-primary':'btn-secondary' ?>" href="?page=<?=client_h($key)?>"><?=client_h($label)?></a><?php endforeach?></nav>
<?php if(!$items):?><section class="card"><div class="empty"><h2>Aucun contenu publié pour le moment</h2><p>Revenez bientôt pour découvrir les nouveautés.</p></div></section><?php else:?><section class="tourism-content-grid"><?php foreach($items as $item):$title=(string)($item['titre']??$item['nom']??'');$image=(string)($item['image_url']??'');?><article class="card tourism-content-card"><?php if($image!==''):?><img src="<?=client_h($image)?>" alt="" loading="lazy"><?php endif?><div class="tourism-content-copy"><p class="eyebrow"><?=client_h($item['categorie']??$item['type']??$contentLabels[$contentType])?></p><h2><?=client_h($title)?></h2><?php if($contentType==='promotions'):?><p><?=client_h($item['reduction']??'')?></p><p>Du <?=client_h(client_format_date($item['date_debut']??null))?> au <?=client_h(client_format_date($item['date_fin']??null))?></p><?php elseif($contentType==='hebergements'):?><p><?=client_h($item['localite']??'')?> · <?=client_h(client_money($item['prix_min']??null,$item['devise']??'XOF'))?> / nuit</p><?php elseif($contentType==='activites'):?><p><?=client_h($item['localite']??'')?> · <?=client_h(client_money($item['prix']??null,$item['devise']??'XOF'))?></p><?php endif?><p><?=nl2br(client_h($item['resume']??$item['description']??$item['contenu']??''))?></p><?php if($slug!==''):?><a class="btn btn-secondary" href="?page=<?=client_h($contentType)?>">Retour à la liste</a><?php else:?><a class="btn btn-secondary" href="?page=<?=client_h($contentType)?>&slug=<?=rawurlencode((string)$item['slug'])?>">Voir les détails</a><?php endif?></div></article><?php endforeach?></section><?php endif?>
<style>.content-tabs{display:flex;gap:.5rem;flex-wrap:wrap;margin:1rem 0}.tourism-content-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,280px),1fr));gap:1rem}.tourism-content-card{overflow:hidden}.tourism-content-card>img{width:100%;height:200px;object-fit:cover}.tourism-content-copy{padding:1rem}.tourism-content-copy h2{font-size:1.15rem}.tourism-content-copy p{line-height:1.6}</style>
